(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.012-t*0.15)*8+Math.cos((y+w1y)*0.01+t*0.18)*6;
  const w2y = Math.cos((y+w1y)*0.013+t*0.12)*8+Math.sin((x+w1x)*0.011-t*0.2)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [200+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*60,0.11,2.1],
    [350+Math.cos(t*0.55+1)*60,200+Math.sin(t*0.75+4)*50,0.05,1.8],
    [80+Math.sin(t*0.7+5)*90,100+Math.cos(t*0.35+3)*70,0.09,2.4],
    [300+Math.cos(t*0.42+2)*110,30+Math.sin(t*0.58+1)*40,0.13,1.6]
  ];
  let aS=0,iS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
  }
  const act=aS/10,inh=iS/10;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.06+sy*0.08-t*1.8)*0.15+Math.sin(sx*0.05-sy*0.07+t*1.4)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const fib=Math.sin(dist*0.03-ang*2.618-t*0.8)*0.3;
  const hx=sx*0.1,hy=sy*0.1*0.866;
  const hex=Math.sin((hx-Math.round(hx)+hy-Math.round(hy))*Math.PI*2+t*0.5)*0.2;
  const cross=Math.sin(act*inh*3+t*0.3)*0.2;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+fib+hex+cross)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const cell2=Math.tanh(Math.sin(sx*0.07+sy*0.09-t*0.4)*Math.cos(sx*0.11-sy*0.06+t*0.6))*0.15;
  const blend=reaction*0.6+cell*0.2+cell2*0.2,v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,40,80],[15,85,115],[20,155,145],[80,200,160],[180,210,120],[240,200,80],[245,150,70],[220,100,80],[180,60,90],[120,40,100],[60,25,80],[20,15,55],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.05:0.95;
  const glow=Math.max(0,reaction)*0.15;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*30)|0
  ];
}
